#!/usr/bin/env bash
# R11 look lane: desktop backdrops (sides of the phone column) + per-chapter map backgrounds.
# ONE draw at a time via studio/bin/art.sh. usage: look-art.sh [name...]   (FORCE=1 redraws)
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. Absolutely no text, no letters, no numbers, no logo, no watermark, no UI, no frame, no border."
M="Portrait 2:3 full-bleed game background, NO magenta, seen from straight above like a mobile puzzle saga map. The whole centre (the middle 60 percent of the width) is open calm ground with NO path, NO road, no buildings, no characters, no cats, low contrast so game buttons read on top of it. Small decorations only near the far left and far right edges, nothing large cut by the top or bottom edge. Even soft lighting."
D="Wide 16:9 landscape full-bleed scene, NO magenta, eye-level view down a cozy cartoon cat town street with soft depth and atmospheric haze. The MIDDLE THIRD of the image is calm and simple (open cobblestone square, soft sky, distant blurred houses, nothing important there) because a game window covers it. All the rich detail is in the LEFT THIRD and the RIGHT THIRD: tall cat-cafe and shop fronts with striped awnings, round windows with cats peeking out, cats napping on rooftops, chimneys, flower boxes, potted plants, a bicycle with a basket, bunting. Shop signs are blank wooden boards with only paw or fish icons, never letters."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; echo "done $n $(ls -la "$n.png" 2>&1 | awk '{print $5}') $(date +%T)"; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run look-desk-day && g look-desk-day "$D Time: bright late-morning sunshine, clear blue sky with a few puffy clouds, crisp warm light from the upper right. $S"
run look-map-autumn && g look-map-autumn "$M Theme: an autumn park lawn: warm ochre and olive grass with drifts of orange, red and golden fallen maple leaves, a few small round orange-leaved bushes, acorns and tiny mushrooms near the edges, a couple of flat round stepping stones, small paw prints. Warm afternoon sunlight from the upper right. $S"
run look-map-snow && g look-map-snow "$M Theme: a snowy village green: soft fresh snow ground with gentle mounds in ivory and pale blue shadow, small snow-capped round evergreen bushes and tiny snowy pine trees near the edges, a little snowman made of three snowballs with no face text, red berries, small paw prints in the snow. Cool soft winter daylight with a warm touch from the upper right. $S"
run look-map-lantern && g look-map-lantern "$M Theme: a tea garden at night: deep teal and indigo night lawn with soft moss, small round paper lanterns glowing warm honey near the edges, tiny fireflies, a few round dark bushes with small white night flowers, flat round stepping stones lit by lantern glow, small paw prints. Gentle moonlight, the centre stays calm and evenly dim but not black. $S"
run look-map-beach && g look-map-beach "$M Theme: a seaside boardwalk beach: soft warm sand ground with gentle ripples, at the far left edge a strip of honey oak boardwalk planks running top to bottom, at the far right edge a thin band of turquoise shallow water with foam, small seashells, starfish, a tiny bucket and spade, beach grass tufts, small paw prints in the sand. Bright summer sunlight from the upper right. $S"
run look-map-bakery && g look-map-bakery "$M Theme: a candy bakery district plaza: soft pastel pink and cream tiled ground like frosting, with sprinkles scattered lightly, near the edges small cupcakes, macarons, round cookies, candy-striped little posts and pastel bushes shaped like gumdrops, small paw prints. Warm soft sunlight from the upper right. $S"
run look-desk-sunset && g look-desk-sunset "$D Time: golden-hour sunset, peach and rose sky, long warm shadows, glowing windows and warm string lights just turning on. $S"
run look-desk-snow && g look-desk-snow "$D Time: snowy winter evening, soft snowfall, snow on rooftops and awnings, glowing amber windows, wreaths and warm string lights, blue dusk sky. $S"
run look-desk-night && g look-desk-night "$D Time: calm starry night, deep indigo sky full of stars and a big soft moon, lantern-lit street, glowing cosy windows, cats silhouetted on rooftops watching the moon. $S"
echo all-done
